#include <array>
#include <cstddef>
#include <vector>
#include <omp.h>

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize output bins
    bins.fill(0);

    const int max_threads = omp_get_max_threads();
    std::vector<std::array<size_t, 10>> local(static_cast<size_t>(max_threads));
    for (auto &a : local) a.fill(0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lbins = local[static_cast<size_t>(tid)];

        #pragma omp for nowait
        for (std::size_t i = 0; i < x.size(); ++i) {
            double v = x[i];

            // Clamp to [0, 100] and map to bin [0..9]
            // Values are specified to be within [0,100] inclusive, but be robust.
            if (v < 0.0) v = 0.0;
            if (v > 100.0) v = 100.0;

            std::size_t b = static_cast<std::size_t>(v / 10.0);
            if (b >= 10) b = 9; // ensure 100 goes to last bin
            lbins[b] += 1;
        }
    }

    // Combine thread-local bins (serial, avoids races)
    for (int t = 0; t < max_threads; ++t) {
        for (std::size_t b = 0; b < 10; ++b) {
            bins[b] += local[static_cast<size_t>(t)][b];
        }
    }
}
